Proceso PromedioCuatro
    Definir Mutable n1 Como Entero <- 0;
    Definir Mutable n2 Como Entero <- 0;
    Definir Mutable n3 Como Entero <- 0;
    Definir Mutable n4 Como Entero <- 0;
    Leer n1, n2, n3, n4;
    Definir promedio Como Real <- (n1 + n2 + n3 + n4) / 4;
    Escribir promedio;
FinProceso
